powerpagecomponent.content:
{
  "source": "{%- comment -%}
Donate / Complete – FINAL (Web API authoritative)

URL:
  /Donate/Complete/?acceptanceid=<guid>&token=<clientToken>

Design goals:
- Web API is the single source of truth
- Handle eventual consistency from Dataverse / Power Automate
- Cache-busting to minimise portal staleness
- Clean UX while processing
{%- endcomment -%}

{%- assign acceptanceid = request.params.acceptanceid | default: '' | strip -%}
{%- assign token = request.params.token | default: '' | strip -%}

<style>
.wrap{max-width:980px;margin:0 auto;padding:28px 16px 84px;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;color:#0f172a;}
.card{background:#fff;border:1px solid rgba(15,23,42,.08);border-radius:26px;overflow:hidden;box-shadow:0 16px 40px rgba(15,23,42,.10);}
.heroimg{width:100%;aspect-ratio:16/6;overflow:hidden;background:#0b1220;border-bottom:1px solid rgba(15,23,42,.08);display:none;}
.heroimg img{width:100%;height:100%;object-fit:cover;display:block;}
.header{padding:22px 26px;border-bottom:1px solid rgba(15,23,42,.08);}
.title{margin:0;font-size:clamp(24px,3vw,34px);font-weight:900;}
.sub{margin-top:8px;color:rgba(15,23,42,.72);}
.body{padding:20px 26px;}
.panel{border:1px solid rgba(15,23,42,.10);border-radius:20px;padding:16px;background:rgba(15,23,42,.02);}
.row{display:flex;justify-content:space-between;margin:8px 0;}
.label{color:rgba(15,23,42,.7);font-size:13px;}
.value{font-weight:900;}
.state{margin-top:16px;padding:16px;border-radius:16px;background:#fff;border:1px solid rgba(15,23,42,.10);}
.pill{display:inline-flex;gap:10px;align-items:center;border-radius:999px;padding:10px 12px;border:1px solid rgba(15,23,42,.10);}
.dot{width:10px;height:10px;border-radius:999px;background:#3b82f6;}
.dot.ok{background:#10b981;}
.big{font-size:18px;font-weight:900;margin-top:10px;}
.muted{color:rgba(15,23,42,.7);}
.notice{margin-top:12px;color:rgba(15,23,42,.6);font-size:13px;}
.cta{margin-top:16px;}
.btn{padding:12px 18px;border-radius:999px;border:1px solid rgba(15,23,42,.12);background:#0f172a;color:#fff;font-weight:850;text-decoration:none;}
</style>

<div class="wrap">
  <div class="card">

    <div class="heroimg" id="hero">
      <img id="heroImg" src="" alt="" />
    </div>

    <div class="header">
      <h1 class="title" id="pageTitle">Processing your payment…</h1>
      <div class="sub" id="pageSubtitle">Please wait while we confirm your payment.</div>
    </div>

    <div class="body">

      <div class="panel">
        <div class="row"><div class="label">Offering</div><div class="value" id="offeringName">—</div></div>
        <div class="row"><div class="label">Amount</div><div class="value" id="amountDisplay">—</div></div>
        <div class="row"><div class="label">Receipt email</div><div class="value" id="emailDisplay">—</div></div>
        <div class="muted" id="refDisplay"></div>
      </div>

      <div class="state">
        <div class="pill">
          <span class="dot" id="statusDot"></span>
          <span id="statusText">Still processing</span>
        </div>

        <div class="big" id="stateTitle">Processing</div>
        <div class="muted" id="stateDetail">Waiting for confirmation…</div>

        <div class="notice" id="consistencyNote">
          This can take a short moment while we receive confirmation. You don’t need to refresh the page.
        </div>

        <div class="cta" id="ctaRow"></div>
      </div>

    </div>
  </div>
</div>

<script>
(function(){
  const acceptanceId = "{{ acceptanceid | escape }}";
  const token = "{{ token | escape }}";
  const STATUS_COMPLETED = 815390003;
  const STATUS_PAID = 815390003;
  let pollingStopped = false;

  function stopPolling(){
    pollingStopped = true;
  }

  if(!acceptanceId){
    document.getElementById("pageTitle").textContent = "Invalid session";
    document.getElementById("pageSubtitle").textContent = "Missing acceptance reference.";
    return;
  }

  function cacheBust(){
    return new Date().toISOString();
  }

  function apiUrl(){
    return "/_api/hit_offeringacceptances(" + acceptanceId + ")" +
      "?$select=hit_name,hit_email,hit_totalamount,hit_baseamount,hit_donationaddonamount,hit_acceptancestatus,hit_clienttoken" +
      "&$expand=hit_Offering($select=hit_offeringname,hit_imageurl)" +
      "&$filter=modifiedon lt " + encodeURIComponent(cacheBust());
  }

  function money(n){
    if(n === null || n === undefined) return "—";
    const x = Number(n);
    if(Number.isNaN(x)) return "—";
    return "$" + (Math.round(x) === x ? x.toFixed(0) : x.toFixed(2));
  }

  function render(data){
    if(token && data.hit_clienttoken && token !== data.hit_clienttoken){
      document.getElementById("pageTitle").textContent = "Invalid session";
      document.getElementById("pageSubtitle").textContent = "Security token mismatch.";
      return true;
    }

    document.getElementById("offeringName").textContent =
      data.hit_Offering?.hit_offeringname || "—";

    document.getElementById("emailDisplay").textContent =
      data.hit_email || "—";

    const amt =
      (Number(data.hit_totalamount) > 0)
        ? data.hit_totalamount
        : ((Number(data.hit_baseamount)||0) + (Number(data.hit_donationaddonamount)||0));

    document.getElementById("amountDisplay").textContent = money(amt);
    document.getElementById("refDisplay").textContent = "Reference: " + (data.hit_name || "");

    const img = data.hit_Offering?.hit_imageurl;
    if(img){
      document.getElementById("heroImg").src = img;
      document.getElementById("hero").style.display = "block";
    }

    const status = Number(data.hit_acceptancestatus);

    if(status === STATUS_COMPLETED || status === STATUS_PAID){
      stopPolling();
      document.getElementById("pageTitle").textContent = "Thank you!";
      document.getElementById("pageSubtitle").textContent = "Your donation has been received.";
      document.getElementById("statusDot").classList.add("ok");
      document.getElementById("statusText").textContent = "Payment confirmed";
      document.getElementById("stateTitle").textContent = "Donation successful";
      document.getElementById("stateDetail").textContent = "Thank you for your generosity.";
      document.getElementById("consistencyNote").style.display = "none";
      document.getElementById("ctaRow").innerHTML =
        '<a class="btn" href="/Offerings/">Browse offerings</a>';
      return true;
    }

    return false;
  }

  function poll(){
    if (pollingStopped) {
      return;
    }

    fetch(apiUrl(), { headers:{Accept:"application/json"}, cache:"no-store" })
      .then(r => r.json())
      .then(d => {
        const done = render(d);
        if(!done && !pollingStopped) setTimeout(poll, 2000);
      })
      .catch(() => {
        if (!pollingStopped) setTimeout(poll, 3000);
      });
  }

  poll();
})();
</script>
"
}
